import { LineChartAdapter, useLineChart } from '@dreadnought/react/unstyled';
const series=[{id:'a',label:'A',data:[{x:0,y:20},{x:1,y:40}]}];
function Summary() { const {visible}= useLineChart(); return <p>Видимых серий: {visible.length}</p>; }
export function Example() { return <LineChartAdapter label="Данные" series={series} xDomain={[0,1]} yDomain={[0,50]}><Summary /><LineChartAdapter.Legend>{({defaultContent}) => <span>{defaultContent}</span>}</LineChartAdapter.Legend><LineChartAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</LineChartAdapter.Plot><LineChartAdapter.RangeControls /><LineChartAdapter.Table /><LineChartAdapter.Pagination /><LineChartAdapter.Empty /></LineChartAdapter>; }
